// --- llmtool.FDb.model.AllocMem
// Allocate space for one element. If no memory available, return NULL.
void* llmtool::model_AllocMem() {
    u64 new_nelems     = _db.model_n+1;
    // compute level and index on level
    u64 bsr   = algo::u64_BitScanReverse(new_nelems);
    u64 base  = u64(1)<<bsr;
    u64 index = new_nelems-base;
    void *ret = NULL;
    // if level doesn't exist yet, create it
    llmtool::FModel*  lev   = NULL;
    if (bsr < 36) {
        lev = _db.model_lary[bsr];
        if (!lev) {
            lev=(llmtool::FModel*)algo_lib::malloc_AllocMem(sizeof(llmtool::FModel) * (u64(1)<<bsr));
            _db.model_lary[bsr] = lev;
        }
    }
    // allocate element from this level
    if (lev) {
        _db.model_n = i64(new_nelems);
        ret = lev + index;
    }
    return ret;
}

