// --- llmtool.FDb.ind_model.InsertMaybe
// Insert row into hash table. Return true if row is reachable through the hash after the function completes.
bool llmtool::ind_model_InsertMaybe(llmtool::FModel& row) {
    bool retval = true; // if already in hash, InsertMaybe returns true
    if (LIKELY(row.ind_model_next == (llmtool::FModel*)-1)) {// check if in hash already
        row.ind_model_hashval = algo::Smallstr50_Hash(0, row.model);
        ind_model_Reserve(1);
        u32 index = row.ind_model_hashval & (_db.ind_model_buckets_n - 1);
        llmtool::FModel* *prev = &_db.ind_model_buckets_elems[index];
        do {
            llmtool::FModel* ret = *prev;
            if (!ret) { // exit condition 1: reached the end of the list
                break;
            }
            if ((*ret).model == row.model) { // exit condition 2: found matching key
                retval = false;
                break;
            }
            prev = &ret->ind_model_next;
        } while (true);
        if (retval) {
            row.ind_model_next = *prev;
            _db.ind_model_n++;
            *prev = &row;
        }
    }
    return retval;
}

// --- llmtool.FDb.ind_model.Remove
// Remove reference to element from hash index. If element is not in hash, do nothing
void llmtool::ind_model_Remove(llmtool::FModel& row) {
    if (LIKELY(row.ind_model_next != (llmtool::FModel*)-1)) {// check if in hash already
        u32 index = row.ind_model_hashval & (_db.ind_model_buckets_n - 1);
        llmtool::FModel* *prev = &_db.ind_model_buckets_elems[index]; // addr of pointer to current element
        while (llmtool::FModel *next = *prev) {                          // scan the collision chain for our element
            if (next == &row) {        // found it?
                *prev = next->ind_model_next; // unlink (singly linked list)
                _db.ind_model_n--;
                row.ind_model_next = (llmtool::FModel*)-1;// not-in-hash
                break;
            }
            prev = &next->ind_model_next;
        }
    }
}

// --- llmtool.FDb.ind_model.Reserve
// Reserve enough room in the hash for N more elements. Return success code.
void llmtool::ind_model_Reserve(int n) {
    ind_model_AbsReserve(_db.ind_model_n + n);
}

// --- llmtool.FDb.ind_model.AbsReserve
// Reserve enough room for exacty N elements. Return success code.
void llmtool::ind_model_AbsReserve(int n) {
    u32 old_nbuckets = _db.ind_model_buckets_n;
    u32 new_nelems   = n;
    // # of elements has to be roughly equal to the number of buckets
    if (new_nelems > old_nbuckets) {
        int new_nbuckets = i32_Max(algo::BumpToPow2(new_nelems), u32(4));
        u32 old_size = old_nbuckets * sizeof(llmtool::FModel*);
        u32 new_size = new_nbuckets * sizeof(llmtool::FModel*);
        // allocate new array. we don't use Realloc since copying is not needed and factor of 2 probably
        // means new memory will have to be allocated anyway
        llmtool::FModel* *new_buckets = (llmtool::FModel**)algo_lib::malloc_AllocMem(new_size);
        if (UNLIKELY(!new_buckets)) {
            FatalErrorExit("llmtool.out_of_memory  field:llmtool.FDb.ind_model");
        }
        memset(new_buckets, 0, new_size); // clear pointers
        // rehash all entries
        for (int i = 0; i < _db.ind_model_buckets_n; i++) {
            llmtool::FModel* elem = _db.ind_model_buckets_elems[i];
            while (elem) {
                llmtool::FModel &row        = *elem;
                llmtool::FModel* next       = row.ind_model_next;
                u32 index          = row.ind_model_hashval & (new_nbuckets-1);
                row.ind_model_next     = new_buckets[index];
                new_buckets[index] = &row;
                elem               = next;
            }
        }
        // free old array
        algo_lib::malloc_FreeMem(_db.ind_model_buckets_elems, old_size);
        _db.ind_model_buckets_elems = new_buckets;
        _db.ind_model_buckets_n = new_nbuckets;
    }
}

