// --- llmtool.FDb.bh_stat.Dealloc
// Remove all elements from heap and free memory used by the array.
void llmtool::bh_stat_Dealloc() {
    bh_stat_RemoveAll();
    algo_lib::malloc_FreeMem(_db.bh_stat_elems, sizeof(llmtool::FStat*)*_db.bh_stat_max);
    _db.bh_stat_max   = 0;
    _db.bh_stat_elems = NULL;
}

// --- llmtool.FDb.bh_stat.Downheap
// Find new location for ROW starting at IDX
// NOTE: Rest of heap is rearranged, but pointer to ROW is NOT stored in array.
static int llmtool::bh_stat_Downheap(llmtool::FStat& row, int idx) {
    llmtool::FStat* *elems = _db.bh_stat_elems;
    int n = _db.bh_stat_n;
    int child = idx*2+1;
    while (child < n) {
        llmtool::FStat* p = elems[child]; // left child
        int rchild = child+1;
        if (rchild < n) {
            llmtool::FStat* q = elems[rchild]; // right child
            if (bh_stat_ElemLt(*q,*p)) {
                child = rchild;
                p     = q;
            }
        }
        if (!bh_stat_ElemLt(*p,row)) {
            break;
        }
        p->bh_stat_idx   = idx;
        elems[idx]     = p;
        idx            = child;
        child          = idx*2+1;
    }
    return idx;
}

// --- llmtool.FDb.bh_stat.Insert
// Insert row. Row must not already be in index. If row is already in index, do nothing.
void llmtool::bh_stat_Insert(llmtool::FStat& row) {
    if (LIKELY(row.bh_stat_idx == -1)) {
        bh_stat_Reserve(1);
        int n = _db.bh_stat_n;
        _db.bh_stat_n = n + 1;
        int new_idx = bh_stat_Upheap(row, n);
        row.bh_stat_idx = new_idx;
        _db.bh_stat_elems[new_idx] = &row;
    }
}

// --- llmtool.FDb.bh_stat.Reheap
// If row is in heap, update its position. If row is not in heap, insert it.
// Return new position of item in the heap (0=top)
i32 llmtool::bh_stat_Reheap(llmtool::FStat& row) {
    int old_idx = row.bh_stat_idx;
    bool isnew = old_idx == -1;
    if (isnew) {
        bh_stat_Reserve(1);
        old_idx = _db.bh_stat_n++;
    }
    int new_idx = bh_stat_Upheap(row, old_idx);
    if (!isnew && new_idx == old_idx) {
        new_idx = bh_stat_Downheap(row, old_idx);
    }
    row.bh_stat_idx = new_idx;
    _db.bh_stat_elems[new_idx] = &row;
    return new_idx;
}

// --- llmtool.FDb.bh_stat.ReheapFirst
// Key of first element in the heap changed. Move it.
// This function does not check the insert condition.
// Return new position of item in the heap (0=top).
// Heap must be non-empty or behavior is undefined.
i32 llmtool::bh_stat_ReheapFirst() {
    llmtool::FStat &row = *_db.bh_stat_elems[0];
    i32 new_idx = bh_stat_Downheap(row, 0);
    row.bh_stat_idx = new_idx;
    _db.bh_stat_elems[new_idx] = &row;
    return new_idx;
}

// --- llmtool.FDb.bh_stat.Remove
// Remove element from index. If element is not in index, do nothing.
void llmtool::bh_stat_Remove(llmtool::FStat& row) {
    if (bh_stat_InBheapQ(row)) {
        int old_idx = row.bh_stat_idx;
        if (_db.bh_stat_elems[old_idx] == &row) { // sanity check: heap points back to row
            row.bh_stat_idx = -1;           // mark not in heap
            i32 n = _db.bh_stat_n - 1; // index of last element in heap
            _db.bh_stat_n = n;         // decrease count
            if (old_idx != n) {
                llmtool::FStat *elem = _db.bh_stat_elems[n];
                int new_idx = bh_stat_Upheap(*elem, old_idx);
                if (new_idx == old_idx) {
                    new_idx = bh_stat_Downheap(*elem, old_idx);
                }
                elem->bh_stat_idx = new_idx;
                _db.bh_stat_elems[new_idx] = elem;
            }
        }
    }
}

// --- llmtool.FDb.bh_stat.RemoveAll
// Remove all elements from binary heap
void llmtool::bh_stat_RemoveAll() {
    int n = _db.bh_stat_n;
    for (int i = n - 1; i>=0; i--) {
        _db.bh_stat_elems[i]->bh_stat_idx = -1; // mark not-in-heap
    }
    _db.bh_stat_n = 0;
}

// --- llmtool.FDb.bh_stat.RemoveFirst
// If index is empty, return NULL. Otherwise remove and return first key in index.
//  Call 'head changed' trigger.
llmtool::FStat* llmtool::bh_stat_RemoveFirst() {
    llmtool::FStat *row = NULL;
    if (_db.bh_stat_n > 0) {
        row = _db.bh_stat_elems[0];
        row->bh_stat_idx = -1;           // mark not in heap
        i32 n = _db.bh_stat_n - 1; // index of last element in heap
        _db.bh_stat_n = n;         // decrease count
        if (n) {
            llmtool::FStat &elem = *_db.bh_stat_elems[n];
            int new_idx = bh_stat_Downheap(elem, 0);
            elem.bh_stat_idx = new_idx;
            _db.bh_stat_elems[new_idx] = &elem;
        }
    }
    return row;
}

// --- llmtool.FDb.bh_stat.Reserve
// Reserve space in index for N more elements
void llmtool::bh_stat_Reserve(int n) {
    i32 old_max = _db.bh_stat_max;
    if (UNLIKELY(_db.bh_stat_n + n > old_max)) {
        u32 new_max  = u32_Max(4, old_max * 2);
        u32 old_size = old_max * sizeof(llmtool::FStat*);
        u32 new_size = new_max * sizeof(llmtool::FStat*);
        void *new_mem = algo_lib::malloc_ReallocMem(_db.bh_stat_elems, old_size, new_size);
        if (UNLIKELY(!new_mem)) {
            FatalErrorExit("llmtool.out_of_memory  field:llmtool.FDb.bh_stat");
        }
        _db.bh_stat_elems = (llmtool::FStat**)new_mem;
        _db.bh_stat_max = new_max;
    }
}

// --- llmtool.FDb.bh_stat.Upheap
// Find and return index of new location for element ROW in the heap, starting at index IDX.
// Move any elements along the way but do not modify ROW.
static int llmtool::bh_stat_Upheap(llmtool::FStat& row, int idx) {
    llmtool::FStat* *elems = _db.bh_stat_elems;
    while (idx>0) {
        int j = (idx-1)/2;
        llmtool::FStat* p = elems[j];
        if (!bh_stat_ElemLt(row, *p)) {
            break;
        }
        p->bh_stat_idx = idx;
        elems[idx] = p;
        idx = j;
    }
    return idx;
}

// --- llmtool.FDb.bh_stat.ElemLt
inline static bool llmtool::bh_stat_ElemLt(llmtool::FStat &a, llmtool::FStat &b) {
    (void)_db;
    return stat_Lt(a, b);
}

// --- llmtool.FDb.bh_model.Dealloc
// Remove all elements from heap and free memory used by the array.
void llmtool::bh_model_Dealloc() {
    bh_model_RemoveAll();
    algo_lib::malloc_FreeMem(_db.bh_model_elems, sizeof(llmtool::FModel*)*_db.bh_model_max);
    _db.bh_model_max   = 0;
    _db.bh_model_elems = NULL;
}

// --- llmtool.FDb.bh_model.Downheap
// Find new location for ROW starting at IDX
// NOTE: Rest of heap is rearranged, but pointer to ROW is NOT stored in array.
static int llmtool::bh_model_Downheap(llmtool::FModel& row, int idx) {
    llmtool::FModel* *elems = _db.bh_model_elems;
    int n = _db.bh_model_n;
    int child = idx*2+1;
    while (child < n) {
        llmtool::FModel* p = elems[child]; // left child
        int rchild = child+1;
        if (rchild < n) {
            llmtool::FModel* q = elems[rchild]; // right child
            if (bh_model_ElemLt(*q,*p)) {
                child = rchild;
                p     = q;
            }
        }
        if (!bh_model_ElemLt(*p,row)) {
            break;
        }
        p->bh_model_idx   = idx;
        elems[idx]     = p;
        idx            = child;
        child          = idx*2+1;
    }
    return idx;
}

// --- llmtool.FDb.bh_model.Insert
// Insert row. Row must not already be in index. If row is already in index, do nothing.
void llmtool::bh_model_Insert(llmtool::FModel& row) {
    if (LIKELY(row.bh_model_idx == -1)) {
        bh_model_Reserve(1);
        int n = _db.bh_model_n;
        _db.bh_model_n = n + 1;
        int new_idx = bh_model_Upheap(row, n);
        row.bh_model_idx = new_idx;
        _db.bh_model_elems[new_idx] = &row;
    }
}

// --- llmtool.FDb.bh_model.Reheap
// If row is in heap, update its position. If row is not in heap, insert it.
// Return new position of item in the heap (0=top)
i32 llmtool::bh_model_Reheap(llmtool::FModel& row) {
    int old_idx = row.bh_model_idx;
    bool isnew = old_idx == -1;
    if (isnew) {
        bh_model_Reserve(1);
        old_idx = _db.bh_model_n++;
    }
    int new_idx = bh_model_Upheap(row, old_idx);
    if (!isnew && new_idx == old_idx) {
        new_idx = bh_model_Downheap(row, old_idx);
    }
    row.bh_model_idx = new_idx;
    _db.bh_model_elems[new_idx] = &row;
    return new_idx;
}

// --- llmtool.FDb.bh_model.ReheapFirst
// Key of first element in the heap changed. Move it.
// This function does not check the insert condition.
// Return new position of item in the heap (0=top).
// Heap must be non-empty or behavior is undefined.
i32 llmtool::bh_model_ReheapFirst() {
    llmtool::FModel &row = *_db.bh_model_elems[0];
    i32 new_idx = bh_model_Downheap(row, 0);
    row.bh_model_idx = new_idx;
    _db.bh_model_elems[new_idx] = &row;
    return new_idx;
}

// --- llmtool.FDb.bh_model.Remove
// Remove element from index. If element is not in index, do nothing.
void llmtool::bh_model_Remove(llmtool::FModel& row) {
    if (bh_model_InBheapQ(row)) {
        int old_idx = row.bh_model_idx;
        if (_db.bh_model_elems[old_idx] == &row) { // sanity check: heap points back to row
            row.bh_model_idx = -1;           // mark not in heap
            i32 n = _db.bh_model_n - 1; // index of last element in heap
            _db.bh_model_n = n;         // decrease count
            if (old_idx != n) {
                llmtool::FModel *elem = _db.bh_model_elems[n];
                int new_idx = bh_model_Upheap(*elem, old_idx);
                if (new_idx == old_idx) {
                    new_idx = bh_model_Downheap(*elem, old_idx);
                }
                elem->bh_model_idx = new_idx;
                _db.bh_model_elems[new_idx] = elem;
            }
        }
    }
}

// --- llmtool.FDb.bh_model.RemoveAll
// Remove all elements from binary heap
void llmtool::bh_model_RemoveAll() {
    int n = _db.bh_model_n;
    for (int i = n - 1; i>=0; i--) {
        _db.bh_model_elems[i]->bh_model_idx = -1; // mark not-in-heap
    }
    _db.bh_model_n = 0;
}

// --- llmtool.FDb.bh_model.RemoveFirst
// If index is empty, return NULL. Otherwise remove and return first key in index.
//  Call 'head changed' trigger.
llmtool::FModel* llmtool::bh_model_RemoveFirst() {
    llmtool::FModel *row = NULL;
    if (_db.bh_model_n > 0) {
        row = _db.bh_model_elems[0];
        row->bh_model_idx = -1;           // mark not in heap
        i32 n = _db.bh_model_n - 1; // index of last element in heap
        _db.bh_model_n = n;         // decrease count
        if (n) {
            llmtool::FModel &elem = *_db.bh_model_elems[n];
            int new_idx = bh_model_Downheap(elem, 0);
            elem.bh_model_idx = new_idx;
            _db.bh_model_elems[new_idx] = &elem;
        }
    }
    return row;
}

// --- llmtool.FDb.bh_model.Reserve
// Reserve space in index for N more elements
void llmtool::bh_model_Reserve(int n) {
    i32 old_max = _db.bh_model_max;
    if (UNLIKELY(_db.bh_model_n + n > old_max)) {
        u32 new_max  = u32_Max(4, old_max * 2);
        u32 old_size = old_max * sizeof(llmtool::FModel*);
        u32 new_size = new_max * sizeof(llmtool::FModel*);
        void *new_mem = algo_lib::malloc_ReallocMem(_db.bh_model_elems, old_size, new_size);
        if (UNLIKELY(!new_mem)) {
            FatalErrorExit("llmtool.out_of_memory  field:llmtool.FDb.bh_model");
        }
        _db.bh_model_elems = (llmtool::FModel**)new_mem;
        _db.bh_model_max = new_max;
    }
}

// --- llmtool.FDb.bh_model.Upheap
// Find and return index of new location for element ROW in the heap, starting at index IDX.
// Move any elements along the way but do not modify ROW.
static int llmtool::bh_model_Upheap(llmtool::FModel& row, int idx) {
    llmtool::FModel* *elems = _db.bh_model_elems;
    while (idx>0) {
        int j = (idx-1)/2;
        llmtool::FModel* p = elems[j];
        if (!bh_model_ElemLt(row, *p)) {
            break;
        }
        p->bh_model_idx = idx;
        elems[idx] = p;
        idx = j;
    }
    return idx;
}

// --- llmtool.FDb.bh_model.ElemLt
inline static bool llmtool::bh_model_ElemLt(llmtool::FModel &a, llmtool::FModel &b) {
    (void)_db;
    return model_Lt(a, b);
}

// --- llmtool.FDb.trace.RowidFind
// find trace by row id (used to implement reflection)
static algo::ImrowPtr llmtool::trace_RowidFind(int t) {
    return algo::ImrowPtr(t==0 ? u64(&_db.trace) : u64(0));
}

// --- llmtool.FDb.trace.N
// Function return 1
inline static i32 llmtool::trace_N() {
    return 1;
}

// --- llmtool.FDb.bh_stat_curs.Add
static void llmtool::_db_bh_stat_curs_Add(_db_bh_stat_curs &curs, llmtool::FStat& row) {
    // the helper heap grows as the walk widens, so a walk that stops early allocates little
    if (curs.temp_n == curs.temp_max) {
        int max = i32_Max(16, curs.temp_max * 2);
        curs.temp_elems = (llmtool::FStat**)algo_lib::malloc_ReallocMem(curs.temp_elems, sizeof(void*) * curs.temp_max, sizeof(void*) * max);
        if (!curs.temp_elems) {
            algo::FatalErrorExit("llmtool.cursor_out_of_memory  func:llmtool.FDb.bh_stat_curs.Add");
        }
        curs.temp_max = max;
    }
    u32 n = curs.temp_n;
    int i = n;
    curs.temp_n = n+1;
    llmtool::FStat* *elems = curs.temp_elems;
    while (i>0) {
        int j = (i-1)/2;
        llmtool::FStat* p = elems[j];
        if (!bh_stat_ElemLt(row,*p)) {
            break;
        }
        elems[i]=p;
        i=j;
    }
    elems[i]=&row;
}

// --- llmtool.FDb.bh_stat_curs.Reset
// Reset cursor. If HEAP is non-empty, add its top element to CURS.
void llmtool::_db_bh_stat_curs_Reset(_db_bh_stat_curs &curs, llmtool::FDb &parent) {
    curs.parent       = &parent;
    curs.temp_n = 0;
    if (parent.bh_stat_n > 0) {
        _db_bh_stat_curs_Add(curs, *parent.bh_stat_elems[0]);
    }
}

// --- llmtool.FDb.bh_stat_curs.Next
// Advance cursor.
void llmtool::_db_bh_stat_curs_Next(_db_bh_stat_curs &curs) {
    llmtool::FStat* *elems = curs.temp_elems;
    int n = curs.temp_n;
    if (n > 0) {
        // remove top element from heap
        llmtool::FStat* dead = elems[0];
        int i       = 0;
        llmtool::FStat* last = curs.temp_elems[n-1];
        // downheap last elem
        do {
            llmtool::FStat* choose = last;
            int l         = i*2+1;
            if (l<n) {
                llmtool::FStat* el = elems[l];
                int r     = l+1;
                r        -= r==n;
                llmtool::FStat* er = elems[r];
                if (bh_stat_ElemLt(*er,*el)) {
                    el  = er;
                    l   = r;
                }
                bool b = bh_stat_ElemLt(*el,*last);
                if (b) choose = el;
                if (!b) l = n;
            }
            elems[i] = choose;
            i = l;
        } while (i < n);
        curs.temp_n = n-1;
        int index = dead->bh_stat_idx;
        i = (index*2+1);
        if (i < bh_stat_N()) {
            llmtool::FStat &elem = *curs.parent->bh_stat_elems[i];
            _db_bh_stat_curs_Add(curs, elem);
        }
        if (i+1 < bh_stat_N()) {
            llmtool::FStat &elem = *curs.parent->bh_stat_elems[i + 1];
            _db_bh_stat_curs_Add(curs, elem);
        }
    }
}

// --- llmtool.FDb.bh_model_curs.Add
static void llmtool::_db_bh_model_curs_Add(_db_bh_model_curs &curs, llmtool::FModel& row) {
    // the helper heap grows as the walk widens, so a walk that stops early allocates little
    if (curs.temp_n == curs.temp_max) {
        int max = i32_Max(16, curs.temp_max * 2);
        curs.temp_elems = (llmtool::FModel**)algo_lib::malloc_ReallocMem(curs.temp_elems, sizeof(void*) * curs.temp_max, sizeof(void*) * max);
        if (!curs.temp_elems) {
            algo::FatalErrorExit("llmtool.cursor_out_of_memory  func:llmtool.FDb.bh_model_curs.Add");
        }
        curs.temp_max = max;
    }
    u32 n = curs.temp_n;
    int i = n;
    curs.temp_n = n+1;
    llmtool::FModel* *elems = curs.temp_elems;
    while (i>0) {
        int j = (i-1)/2;
        llmtool::FModel* p = elems[j];
        if (!bh_model_ElemLt(row,*p)) {
            break;
        }
        elems[i]=p;
        i=j;
    }
    elems[i]=&row;
}

// --- llmtool.FDb.bh_model_curs.Reset
// Reset cursor. If HEAP is non-empty, add its top element to CURS.
void llmtool::_db_bh_model_curs_Reset(_db_bh_model_curs &curs, llmtool::FDb &parent) {
    curs.parent       = &parent;
    curs.temp_n = 0;
    if (parent.bh_model_n > 0) {
        _db_bh_model_curs_Add(curs, *parent.bh_model_elems[0]);
    }
}

// --- llmtool.FDb.bh_model_curs.Next
// Advance cursor.
void llmtool::_db_bh_model_curs_Next(_db_bh_model_curs &curs) {
    llmtool::FModel* *elems = curs.temp_elems;
    int n = curs.temp_n;
    if (n > 0) {
        // remove top element from heap
        llmtool::FModel* dead = elems[0];
        int i       = 0;
        llmtool::FModel* last = curs.temp_elems[n-1];
        // downheap last elem
        do {
            llmtool::FModel* choose = last;
            int l         = i*2+1;
            if (l<n) {
                llmtool::FModel* el = elems[l];
                int r     = l+1;
                r        -= r==n;
                llmtool::FModel* er = elems[r];
                if (bh_model_ElemLt(*er,*el)) {
                    el  = er;
                    l   = r;
                }
                bool b = bh_model_ElemLt(*el,*last);
                if (b) choose = el;
                if (!b) l = n;
            }
            elems[i] = choose;
            i = l;
        } while (i < n);
        curs.temp_n = n-1;
        int index = dead->bh_model_idx;
        i = (index*2+1);
        if (i < bh_model_N()) {
            llmtool::FModel &elem = *curs.parent->bh_model_elems[i];
            _db_bh_model_curs_Add(curs, elem);
        }
        if (i+1 < bh_model_N()) {
            llmtool::FModel &elem = *curs.parent->bh_model_elems[i + 1];
            _db_bh_model_curs_Add(curs, elem);
        }
    }
}

// --- llmtool.FDb..Init
// Set all fields to initial values.
void llmtool::FDb_Init() {
    // initialize LAry model (llmtool.FDb.model)
    _db.model_n = 0;
    memset(_db.model_lary, 0, sizeof(_db.model_lary)); // zero out all level pointers
    llmtool::FModel* model_first = (llmtool::FModel*)algo_lib::malloc_AllocMem(sizeof(llmtool::FModel) * (u64(1)<<4));
    if (!model_first) {
        FatalErrorExit("out of memory");
    }
    for (int i = 0; i < 4; i++) {
        _db.model_lary[i]  = model_first;
        model_first    += 1ULL<<i;
    }
    // initialize hash table for llmtool::FModel;
    _db.ind_model_n             	= 0; // (llmtool.FDb.ind_model)
    _db.ind_model_buckets_n     	= 4; // (llmtool.FDb.ind_model)
    _db.ind_model_buckets_elems 	= (llmtool::FModel**)algo_lib::malloc_AllocMem(sizeof(llmtool::FModel*)*_db.ind_model_buckets_n); // initial buckets (llmtool.FDb.ind_model)
    if (!_db.ind_model_buckets_elems) {
        FatalErrorExit("out of memory"); // (llmtool.FDb.ind_model)
    }
    memset(_db.ind_model_buckets_elems, 0, sizeof(llmtool::FModel*)*_db.ind_model_buckets_n); // (llmtool.FDb.ind_model)
    // initialize LAry req (llmtool.FDb.req)
    _db.req_n = 0;
    memset(_db.req_lary, 0, sizeof(_db.req_lary)); // zero out all level pointers
    llmtool::FReq* req_first = (llmtool::FReq*)algo_lib::malloc_AllocMem(sizeof(llmtool::FReq) * (u64(1)<<4));
    if (!req_first) {
        FatalErrorExit("out of memory");
    }
    for (int i = 0; i < 4; i++) {
        _db.req_lary[i]  = req_first;
        req_first    += 1ULL<<i;
    }
    // initialize hash table for llmtool::FReq;
    _db.ind_req_n             	= 0; // (llmtool.FDb.ind_req)
    _db.ind_req_buckets_n     	= 4; // (llmtool.FDb.ind_req)
    _db.ind_req_buckets_elems 	= (llmtool::FReq**)algo_lib::malloc_AllocMem(sizeof(llmtool::FReq*)*_db.ind_req_buckets_n); // initial buckets (llmtool.FDb.ind_req)
    if (!_db.ind_req_buckets_elems) {
        FatalErrorExit("out of memory"); // (llmtool.FDb.ind_req)
    }
    memset(_db.ind_req_buckets_elems, 0, sizeof(llmtool::FReq*)*_db.ind_req_buckets_n); // (llmtool.FDb.ind_req)
    // initialize LAry dir (llmtool.FDb.dir)
    _db.dir_n = 0;
    memset(_db.dir_lary, 0, sizeof(_db.dir_lary)); // zero out all level pointers
    llmtool::FDir* dir_first = (llmtool::FDir*)algo_lib::malloc_AllocMem(sizeof(llmtool::FDir) * (u64(1)<<4));
    if (!dir_first) {
        FatalErrorExit("out of memory");
    }
    for (int i = 0; i < 4; i++) {
        _db.dir_lary[i]  = dir_first;
        dir_first    += 1ULL<<i;
    }
    // initialize hash table for llmtool::FDir;
    _db.ind_dir_n             	= 0; // (llmtool.FDb.ind_dir)
    _db.ind_dir_buckets_n     	= 4; // (llmtool.FDb.ind_dir)
    _db.ind_dir_buckets_elems 	= (llmtool::FDir**)algo_lib::malloc_AllocMem(sizeof(llmtool::FDir*)*_db.ind_dir_buckets_n); // initial buckets (llmtool.FDb.ind_dir)
    if (!_db.ind_dir_buckets_elems) {
        FatalErrorExit("out of memory"); // (llmtool.FDb.ind_dir)
    }
    memset(_db.ind_dir_buckets_elems, 0, sizeof(llmtool::FDir*)*_db.ind_dir_buckets_n); // (llmtool.FDb.ind_dir)
    // initialize LAry stat (llmtool.FDb.stat)
    _db.stat_n = 0;
    memset(_db.stat_lary, 0, sizeof(_db.stat_lary)); // zero out all level pointers
    llmtool::FStat* stat_first = (llmtool::FStat*)algo_lib::malloc_AllocMem(sizeof(llmtool::FStat) * (u64(1)<<4));
    if (!stat_first) {
        FatalErrorExit("out of memory");
    }
    for (int i = 0; i < 4; i++) {
        _db.stat_lary[i]  = stat_first;
        stat_first    += 1ULL<<i;
    }
    // initialize hash table for llmtool::FStat;
    _db.ind_stat_n             	= 0; // (llmtool.FDb.ind_stat)
    _db.ind_stat_buckets_n     	= 4; // (llmtool.FDb.ind_stat)
    _db.ind_stat_buckets_elems 	= (llmtool::FStat**)algo_lib::malloc_AllocMem(sizeof(llmtool::FStat*)*_db.ind_stat_buckets_n); // initial buckets (llmtool.FDb.ind_stat)
    if (!_db.ind_stat_buckets_elems) {
        FatalErrorExit("out of memory"); // (llmtool.FDb.ind_stat)
    }
    memset(_db.ind_stat_buckets_elems, 0, sizeof(llmtool::FStat*)*_db.ind_stat_buckets_n); // (llmtool.FDb.ind_stat)
    _db.bh_stat_max   	= 0; // (llmtool.FDb.bh_stat)
    _db.bh_stat_n     	= 0; // (llmtool.FDb.bh_stat)
    _db.bh_stat_elems 	= NULL; // (llmtool.FDb.bh_stat)
    _db.bh_model_max   	= 0; // (llmtool.FDb.bh_model)
    _db.bh_model_n     	= 0; // (llmtool.FDb.bh_model)
    _db.bh_model_elems 	= NULL; // (llmtool.FDb.bh_model)

    llmtool::InitReflection();
}

