// --- llmtool.FModel.model.Nextchar
// Extract next character from STR and advance IDX
inline static int llmtool::model_Nextchar(const llmtool::FModel& parent, algo::strptr &str, int &idx) {
    (void)parent;
    int i = idx;
    int ch = str.elems[i];
    i++;
    idx = i;
    return ch;
}

// --- llmtool.FStat.stat.Nextchar
// Extract next character from STR and advance IDX
inline static int llmtool::stat_Nextchar(const llmtool::FStat& parent, algo::strptr &str, int &idx) {
    (void)parent;
    int i = idx;
    int ch = str.elems[i];
    i++;
    idx = i;
    return ch;
}

// --- llmtool.FStat..Init
// Set all fields to initial values.
void llmtool::FStat_Init(llmtool::FStat& parent) {
    parent.n_request = u32(0);
    parent.input = u64(0);
    parent.output = u64(0);
    parent.cache_read = u64(0);
    parent.cache_write = u64(0);
    parent.cache_write_untimed = u64(0);
    parent.usd_input = double(0.0);
    parent.usd_output = double(0.0);
    parent.usd_cache_read = double(0.0);
    parent.usd_cache_write = double(0.0);
    parent.ind_stat_next = (llmtool::FStat*)-1; // (llmtool.FDb.ind_stat) not-in-hash
    parent.ind_stat_hashval = 0; // stored hash value
    parent.bh_stat_idx = -1; // (llmtool.FDb.bh_stat) not-in-heap
}

// --- llmtool.FieldId.value.ToCstr
// Convert numeric value of field to one of predefined string constants.
// If string is found, return a static C string. Otherwise, return NULL.
const char* llmtool::value_ToCstr(const llmtool::FieldId& parent) {
    const char *ret = NULL;
    switch(value_GetEnum(parent)) {
        case llmtool_FieldId_value         : ret = "value";  break;
    }
    return ret;
}

// --- llmtool.FieldId.value.Print
// Convert value to a string. First, attempt conversion to a known string.
// If no string matches, print value as a numeric value.
void llmtool::value_Print(const llmtool::FieldId& parent, algo::cstring &lhs) {
    const char *strval = value_ToCstr(parent);
    if (strval) {
        lhs << strval;
    } else {
        lhs << parent.value;
    }
}

// --- llmtool.FieldId.value.SetStrptrMaybe
// Convert string to field.
// If the string is invalid, do not modify field and return false.
// In case of success, return true
bool llmtool::value_SetStrptrMaybe(llmtool::FieldId& parent, algo::strptr rhs) {
    bool ret = false;
    switch (elems_N(rhs)) {
        case 5: {
            switch (u64(algo::ReadLE32(rhs.elems))|(u64(rhs[4])<<32)) {
                case LE_STR5('v','a','l','u','e'): {
                    value_SetEnum(parent,llmtool_FieldId_value); ret = true; break;
                }
            }
            break;
        }
    }
    return ret;
}

// --- llmtool.FieldId.value.SetStrptr
// Convert string to field.
// If the string is invalid, set numeric value to DFLT
void llmtool::value_SetStrptr(llmtool::FieldId& parent, algo::strptr rhs, llmtool_FieldIdEnum dflt) {
    if (!value_SetStrptrMaybe(parent,rhs)) value_SetEnum(parent,dflt);
}

// --- llmtool.FieldId.value.ReadStrptrMaybe
// Convert string to field. Return success value
bool llmtool::value_ReadStrptrMaybe(llmtool::FieldId& parent, algo::strptr rhs) {
    bool retval = false;
    retval = value_SetStrptrMaybe(parent,rhs); // try symbol conversion
    if (!retval) { // didn't work? try reading as underlying type
        retval = i32_ReadStrptrMaybe(parent.value,rhs);
    }
    return retval;
}

// --- llmtool.FieldId..ReadStrptrMaybe
// Read fields of llmtool::FieldId from an ascii string.
// The format of the string is the format of the llmtool::FieldId's only field
bool llmtool::FieldId_ReadStrptrMaybe(llmtool::FieldId &parent, algo::strptr in_str) {
    bool retval = true;
    retval = retval && value_ReadStrptrMaybe(parent, in_str);
    return retval;
}

// --- llmtool.FieldId..Print
// print string representation of ROW to string STR
// cfmt:llmtool.FieldId.String  printfmt:Raw
void llmtool::FieldId_Print(llmtool::FieldId row, algo::cstring& str) {
    llmtool::value_Print(row, str);
}

// --- llmtool...SizeCheck
inline static void llmtool::SizeCheck() {
}

// --- llmtool...StaticCheck
void llmtool::StaticCheck() {
    algo_assert(_offset_of(llmtool::FieldId, value) + sizeof(((llmtool::FieldId*)0)->value) == sizeof(llmtool::FieldId));
}

// --- llmtool...main
int main(int argc, char **argv) {
    try {
        algo_lib::FDb_Init();
        lib_json::FDb_Init();
        llmtool::FDb_Init();
        algo_lib::_db.argc = argc;
        algo_lib::_db.argv = argv;
        algo_lib::IohookInit();
        algo_lib::_db.clock = algo::CurrSchedTime(); // initialize clock
        llmtool::ReadArgv(); // dmmeta.main:llmtool
        llmtool::Main(); // user-defined main
    } catch(algo_lib::ErrorX &x) {
        prerr("llmtool.error  " << x); // there may be additional hints in DetachBadTags
        algo_lib::_db.exit_code = 1;
    }
    if (algo_lib::_db.last_signal) {
        algo_lib::_db.exit_code = 1;
    }
    try {
        llmtool::FDb_Uninit();
        lib_json::FDb_Uninit();
        algo_lib::FDb_Uninit();
    } catch(algo_lib::ErrorX &) {
        // don't print anything, might crash
        algo_lib::_db.exit_code = 1;
    }
    // only the lower 1 byte makes it to the outside world
    (void)i32_UpdateMin(algo_lib::_db.exit_code,255);
    return algo_lib::_db.exit_code;
}

